from collections import deque

def enclaves(A):
    R,C=A.shape; seen=np.zeros_like(A,dtype=bool); q=deque()
    for r in range(R):
      for c in (0,C-1):
       if A[r,c]==8 and not seen[r,c]:seen[r,c]=1;q.append((r,c))
    for c in range(C):
      for r in (0,R-1):
       if A[r,c]==8 and not seen[r,c]:seen[r,c]=1;q.append((r,c))
    while q:
      r,c=q.popleft()
      for rr,cc in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
       if 0<=rr<R and 0<=cc<C and A[rr,cc]==8 and not seen[rr,cc]:seen[rr,cc]=1;q.append((rr,cc))
